WITH valid_ranked AS (SELECT member_id, order_id, ordered_at, ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY ordered_at, order_id) AS first_order_rank FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0) SELECT o.order_id, o.member_id, o.store_id, o.ordered_at, o.status, o.gross_cents, o.paid_cents, o.refund_cents, o.quantity, o.channel, o.paid_cents - o.refund_cents AS net_cents, m.home_store_id, r.first_order_rank FROM {{ ref('orders') }} o LEFT JOIN {{ ref('members') }} m ON o.member_id = m.member_id LEFT JOIN valid_ranked r ON o.order_id = r.order_id